		{"joined_word", "Grapes(grape)vine is green. Grapes grow.", "ripe grapes(grape)", "mapping_surface_absent"},
		{"hint_joined_word", "Grapes(grape) are ripe.", "ripe grapes(grape)vine", "mapping_surface_absent"},
	} {
