	cleanHint := strings.Repeat("a ", 247) + "grapes"
	candidate := Candidate{"Grapes(grape).", []string{"fruit"}, []CandidateTarget{{"grape", "a small fruit", cleanHint + "(grape)"}}}
	raw, _ := []byte(p0JSON(candidate)), error(nil)
