	if _, err := v.Validate(context.Background(), spec, candidate); err == nil {
		t.Fatal("annotation inflated word count")
	}
	spec.MinimumWords = 1
	candidate.Targets[0].HintPhrase += "."
	if _, err := v.Validate(context.Background(), spec, candidate); err == nil {
		t.Fatal("overlong clean hint accepted")
	}
